def main() -> None:
    args = build_parser().parse_args()

    # retrieve event ids and locations ----------------------------------------------------------------
    events, lats, lons = EVENT_IDS, LATITUDES, LONGITUDES #parse_lat_lon_file(args.input_file)
    # if not lats:
    #     raise SystemExit(f"No valid latitude/longitude pairs found in: {args.input_file}")

    # generate map of event ids to 'generic' STRES ids ------------------------------------------------
    # this is necessary because usgs_ids are codes that may contain information in them
    stres_ids = [i for i in range(len(events))]
    random.seed(RAND_SEED)
    random.shuffle(stres_ids)
    assert len(stres_ids) == len(events)
    event_ids_to_stres_ids_map = {ei:si for ei,si in zip(events, stres_ids)}

    print("Saving event_ids_to_stres_ids_map to ", args.output_dir+os.sep+"EVENT_ID_TO_STRES_ID_MAP.pkl")
    with open(args.output_dir+os.sep+"EVENT_ID_TO_STRES_ID_MAP.pkl", 'wb') as outfile:
        pkl.dump(event_ids_to_stres_ids_map, outfile)

    # generate event partitions -----------------------------------------------------------------------
    region_points: dict[str, list[tuple[float, float]]] = {k: [] for k in REGION_FUNCS}
    events_to_region_map: dict[str, str] = {e: 'None' for e in events}
    for event, lon, lat in zip(events, lons, lats):
        curr_reg = region_for_point(lon, lat)
        region_points[curr_reg].append((lon, lat))
        events_to_region_map[event] = curr_reg
    assert 'None' not in set([events_to_region_map[e] for e in events_to_region_map.keys()])
    
    print("Saving events_to_region_map to ", args.output_dir+os.sep+"EVENT_ID_TO_REGION_NAME_MAP.pkl")
    with open(args.output_dir+os.sep+"EVENT_ID_TO_REGION_NAME_MAP.pkl", 'wb') as outfile:
        pkl.dump(events_to_region_map, outfile)

    # generate plot of partitions ---------------------------------------------------------------------
    region_colors = {
        "REGION1": "tab:blue",
        "REGION2": "tab:orange",
        "REGION3": "tab:green",
        "REGION4": "tab:red",
    }

    fig, ax = plt.subplots(figsize=(20, 10))
    for region_name, points in region_points.items():
        if not points:
            continue
        region_lons = [p[0] for p in points]
        region_lats = [p[1] for p in points]
        ax.scatter(
            region_lons,
            region_lats,
            alpha=args.alpha,
            s=args.size,
            c=region_colors[region_name],
            edgecolors="none",
            label=f"{region_name} ({len(points)})",
        )

    # infer_and_draw_region_boundaries(ax)
    ax.set_xlim(-180, 180)
    ax.set_ylim(-90, 90)
    ax.set_xlabel("Longitude")
    ax.set_ylabel("Latitude")
    ax.set_title(args.title)
    ax.grid(True, alpha=0.2)
    ax.legend(loc="upper right", frameon=True)

    print("Event counts by region:")
    for region_name in REGION_FUNCS:
        print(f"  {region_name}: {len(region_points[region_name])}")
    print(f"  TOTAL: {sum(len(v) for v in region_points.values())}")

    scatter_save_dir = args.output_dir+os.sep+"scatter_plot.png"
    fig.savefig(scatter_save_dir, dpi=200, bbox_inches="tight")
    print(f"Saved plot to: {scatter_save_dir}")
    pass


if __name__ == "__main__":
    main()
